from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find zero-regions; regions not touching the edge are enclosed cavities.
    seen0 = [[False] * w for _ in range(h)]
    cavities = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or seen0[r][c]:
                continue
            q = deque([(r, c)])
            seen0[r][c] = True
            region = []
            touches_edge = False
            while q:
                y, x = q.popleft()
                region.append((y, x))
                if y == 0 or y == h - 1 or x == 0 or x == w - 1:
                    touches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0
                            and not seen0[ny][nx]):
                        seen0[ny][nx] = True
                        q.append((ny, nx))
            if not touches_edge:
                cavities.append(region)

    # Find four-connected components of 1s.
    comp_id = [[-1] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or comp_id[r][c] != -1:
                continue
            idx = len(components)
            q = deque([(r, c)])
            comp_id[r][c] = idx
            component = []
            while q:
                y, x = q.popleft()
                component.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1
                            and comp_id[ny][nx] == -1):
                        comp_id[ny][nx] = idx
                        q.append((ny, nx))
            components.append(component)

    active = set()
    for region in cavities:
        for y, x in region:
            # Color only the cavity's boundary layer.
            near_one = False
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1):
                        near_one = True
                        active.add(comp_id[ny][nx])
            if near_one:
                out[y][x] = 3

    # Add a one-cell eight-neighbor halo around components enclosing cavities.
    for idx in active:
        for y, x in components[idx]:
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w
                            and grid[ny][nx] == 0 and out[ny][nx] == 0):
                        out[ny][nx] = 2

    return out
